# Code snippet to check for password hashing and JWT generation
import hashlib
import jwt

def hash_password(password: str) -> str:
    return hashlib.sha256(password.encode()).hexdigest()

def generate_jwt_token(data: dict, secret: str) -> str:
    return jwt.encode(data, secret, algorithm="HS256")

# Example usage
hashed_password = hash_password("mySecretPassword")
token = generate_jwt_token({"user": "user@example.com"}, "my_secret_key")

print(hashed_password)
print(token)
